/bin/bash -lc "python3 - <<'PY'
import subprocess,json
r=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','run://r-001'],text=True))
print('TOP_KEYS',list(r))
for k,v in r.items():
 if k not in ('context','study_schema'): print(k,json.dumps(v))
c=r['context']; print('CONTEXT_KEYS',list(c))
for k,v in c.items():
 if k not in ('history','knowledge_access_log','knowledge_log','agent_memory'): print(k,json.dumps(v)[:24000])
print('HISTORY_SUMMARY')
for h in c.get('history',[]):
 print(json.dumps({k:v for k,v in h.items() if k not in ('validation','config','candidate_diagnostics')},default=str)); print('config',json.dumps(h.get('config'))); print('validation',{k:v for k,v in (h.get('validation') or {}).items() if k"'!='"'slices'}); print('diagnostics',json.dumps(h.get('candidate_diagnostics')))
PY"

