import ast,math,itertools,random
from pathlib import Path
# One-coordinate numeric adapter: exercises actual helper AST arithmetic only.
# It is not PyTorch and cannot validate broadcasting across batch/field/action.
class T:
 def __init__(self,x):self.x=x;self.device=None
 @property
 def shape(self):return (len(self.x),) if isinstance(self.x,list) else ()
 def unary(self,f):return T([f(x) for x in self.x] if isinstance(self.x,list) else f(self.x))
 def op(self,o,f):
  a=self.x;b=o.x if isinstance(o,T) else o
  if isinstance(a,list) and isinstance(b,list):assert len(a)==len(b);return T([f(x,y) for x,y in zip(a,b)])
  if isinstance(a,list):return T([f(x,b) for x in a])
  if isinstance(b,list):return T([f(a,y) for y in b])
  return T(f(a,b))
 def __add__(self,o):return self.op(o,lambda a,b:a+b)
 def __radd__(self,o):return self+o
 def __sub__(self,o):return self.op(o,lambda a,b:a-b)
 def __rsub__(self,o):return self.op(o,lambda a,b:b-a)
 def __mul__(self,o):return self.op(o,lambda a,b:a*b)
 def __rmul__(self,o):return self*o
 def __truediv__(self,o):return self.op(o,lambda a,b:a/b)
 def __gt__(self,o):return self.op(o,lambda a,b:a>b)
 def float(self):return self.unary(float)
 def long(self):return self.unary(int)
 def sum(self,dim=-1):return T(sum(self.x))
 def unsqueeze(self,dim):return self
 def clamp_min(self,x):return self.unary(lambda a:max(a,x))
 def gather(self,dim,index):return T([self.x[i] for i in index.x])
 def __getitem__(self,key):
  if isinstance(key,tuple):assert key[0] is Ellipsis;key=key[-1]
  return T(self.x[key])
 def cumprod(self,dim=-1):
  out=[];p=1.0
  for v in self.x:p*=v;out.append(p)
  return T(out)
class Torch:
 @staticmethod
 def log1p(x):return x.unary(math.log1p)
 @staticmethod
 def arange(n,device=None):return T(list(range(n)))
tree=ast.parse(Path('nonmatch_run.py').read_text());cls=next(n for n in tree.body if isinstance(n,ast.ClassDef))
ns={'math':math,'torch':Torch}
for n in cls.body:
 if isinstance(n,ast.FunctionDef) and n.name in ('_absence_statistics','_continuation_statistics'):
  exec(compile(ast.Module(body=[n],type_ignores=[]),'<actual-helper>','exec'),ns)
def prefix(xs):
 total=0.0
 for k in range(2,len(xs)+1):total+=math.prod(xs[:k])
 return total
def mass(xs):return xs[0]*sum(xs[1:]) if xs else 0.0
def encode(v,g):return math.log1p(v)/math.log(129) if g>1 else 0.0
cases=0
for g in range(9):
 for vals in itertools.product((0.0,0.5,1.0),repeat=g):
  p=list(vals)+[0.0];valid=[True]*g+[False]
  old=ns['_continuation_statistics'](None,T(p),T(valid));new=ns['_absence_statistics'](None,T(p),T(valid))
  q=[1-v for v in vals]
  expected={'run':encode(prefix(q),g),'mass':encode(mass(q),g),'endpoint':q[0] if g>1 else 0.0}
  expected_old={'newest_run':encode(prefix(vals),g),'oldest_run':encode(prefix(vals[::-1]),g),'noncontiguous_mass':encode(mass(vals),g),'duplicate':vals[0] if g>1 else 0.0}
  for k,x in new.items():assert abs(x.x-expected[k])<1e-12,(g,vals,k,x.x,expected[k]);assert 0<=x.x<=1+1e-12
  for k,x in old.items():assert abs(x.x-expected_old[k])<1e-12
  assert new['run'].x<=new['mass'].x+1e-12
  assert abs(new['endpoint'].x+old['duplicate'].x-(g>1))<1e-12
  if not any(vals):assert abs(new['run'].x-new['mass'].x)<1e-12
  padded=ns['_absence_statistics'](None,T(p+[0.0]*5),T(valid+[False]*5))
  assert all(abs(new[k].x-padded[k].x)<1e-12 for k in new)
  cases+=1
rng=random.Random(79)
for g in (16,64,128):
 for repeat in range(100):
  vals=[rng.choice([0,1,0.25,0.75]) for i in range(g)]
  new=ns['_absence_statistics'](None,T(vals+[0.0]),T([True]*g+[False]))
  q=[1-v for v in vals]
  assert abs(new['run'].x-encode(prefix(q),g))<1e-12
  assert abs(new['mass'].x-encode(mass(q),g))<1e-12
  cases+=1
print('PASS actual helper AST with scalar adapter:',cases,'coordinates; G0..8 exhaustive plus G16/64/128 randomized; bounds, complement, padding, no-match identity, ancestor match semantics')
# Equal endpoints, counts, switch statistics, but different target-absence run.
a=[0,0,1,0,1,1];b=[0,1,0,0,1,1]
def switches(v):return sum(x+y-2*x*y for x,y in zip(v,v[1:]))
assert sum(a)==sum(b) and a[0]==b[0] and a[-1]==b[-1] and switches(a)==switches(b)
assert mass([1-x for x in a])==mass([1-x for x in b])
assert prefix([1-x for x in a])"'!=prefix([1-x for x in b])
print('"'Distinctness witness p=',a,'and',b,'same G, endpoints, mass, switch rates, different complementary prefix length.')
try:import torch
except ModuleNotFoundError:print('PyTorch unavailable as declared: real forward/backward, accelerator cost and scoring remain host-untested.')
